import {icon,type IconName} from './icons';
import {colorMarkup,colorSettingsMarkup} from '../color/panel';
/** M07 PC/tablet production shell. Artwork state remains in EditorController. */
export const RIGHT_BOXES=[
  ['right.layers','レイヤー','layersBox',true],
  ['right.color','色','colorBox',true],
  ['right.brush','ブラシ','brushBox',true],
  ['right.inspector','選んでいる対象','inspectorBox',false],
  ['right.reference','参考資料','referenceBox',false],
  ['right.assets','素材','assetsBox',false],
  ['right.effects','補正・効果','effectsBox',false],
  ['right.navigator','ナビゲーター','navigatorBox',false],
  ['right.history','履歴','historyBox',false],
  ['right.automation','操作セット','automationBox',false],
  ['right.document','作品','documentBox',false],
  ['right.workspace','作業画面','workspaceBox',false],
] as const;
export const FEATURE_CATEGORIES=[
  ['描画','drawing'],['塗り・色','fill-color-region'],
  ['選択・変形','selection-transform'],['ベクター・文字・図形','vector-text-shape'],
  ['定規・ガイド','guides-rulers'],['レイヤー・合成','layers-compositing'],
  ['補正・フィルター・修復','adjust-filter-retouch'],['資料・アセット','reference-assets'],
  ['履歴・自動化','history-automation'],['キャンバス・表示','canvas-view'],
  ['ドキュメント・編集・出力','document-output'],['ワークスペース・設定','workspace-settings'],
] as const;
const railTools=[
  ['paint','brush','ブラシ',true],['erase','eraser','消しゴム',true],
  ['smudge','smudge','ぼかし・混色',true],['eyedropper','eyedropper','スポイト',true],
  ['smartFill','smartFill','塗りつぶし',true],['selection','selection','選択範囲',true],
  ['transform','transform','変形',true],['move','move','移動',true],
  ['shapes','shape','図形',true],['rulers','guide','定規',true],
] as const;
export const DEFAULT_TOOL_ORDER=railTools.map(([id])=>id);
const boxIcons:Record<(typeof RIGHT_BOXES)[number][0],IconName>={
  'right.layers':'layers','right.color':'color','right.brush':'brush',
  'right.inspector':'settings','right.reference':'reference','right.assets':'all',
  'right.effects':'effects','right.navigator':'zoom','right.history':'history',
  'right.automation':'settings','right.document':'document','right.workspace':'workspace',
};
const categoryIcons:readonly IconName[]=[
  'brush','smartFill','transform','shape','guide','layers',
  'effects','reference','history','zoom','document','workspace',
];
const disabled=(label:string)=>'<span class="unavailable" aria-label="'+label+'は後のマイルストーンで利用できます">M07では準備中</span>';
const boxBody=(id:string):string=>{
  switch(id){
    case 'right.layers':return '<div id="layerList" class="layer-list" role="group" aria-label="レイヤー一覧"></div><button id="addLayer" type="button" disabled>'+icon('plus')+' レイヤー追加</button>';
    case 'right.color':return colorMarkup();
    case 'right.brush':return '<label class="checkbox-line"><input id="paintBehind" type="checkbox"> 同じレイヤーの背面に描く</label><div class="m10-presets"><label>ブラシの種類<select id="brush" disabled></select></label><details class="brush-disclosure"><summary>検索・絞り込み</summary><label>ブラシを検索<input id="brushSearch" type="search" placeholder="名前・用途で検索" autocomplete="off"></label><label>種類で絞り込む<select id="brushGroup" aria-label="ブラシの種類で絞り込む"><option value="all">すべて</option><option value="favorites">★ お気に入り</option><option value="recent">最近使った</option><option value="ink">ペン・線画</option><option value="sketch">鉛筆・下描き</option><option value="paint">塗り</option><option value="eraser">消しゴム</option><option value="user">自作ブラシ</option><option value="other">その他</option></select></label><small id="brushCatalogCount" role="status" aria-live="polite"></small></details><details class="brush-disclosure"><summary>ブラシの管理</summary><div class="m10-preset-actions"><button id="brushFavorite" type="button" aria-pressed="false" disabled>☆ お気に入り</button><button id="brushDuplicate" type="button" disabled>複製</button><button id="brushRecoverLast" type="button" title="この作品で直前に描いた線のブラシ設定を取り出す">直前の線から</button><button id="brushRename" type="button" disabled>名前変更</button><button id="brushSave" type="button" disabled>保存</button><button id="brushDelete" type="button" disabled>削除</button></div><div class="m10-preset-actions"><button id="brushImport" type="button">ブラシを読み込む</button><button id="brushExport" type="button">ブラシを書き出す</button><input id="brushImportFile" type="file" accept=".json,application/json" hidden></div><small id="brushLibraryStatus" role="status" aria-live="polite">標準ブラシは複製して編集できます。</small><div class="brush-edit-feedback"><small id="brushModifiedStatus" role="status" aria-live="polite">保存済み</small><button id="brushReset" type="button" disabled>変更を元に戻す</button></div></details></div><details class="brush-disclosure"><summary>描き味を調整</summary><button id="showBrushSize" type="button">ブラシの太さを確認</button><div class="m10-brush-settings"><label>不透明度 <output id="brushOpacityValue">100%</output><input id="brushOpacity" type="range" data-unit="%" min="0" max="100" step="1" value="100" disabled><input id="brushOpacityNumber" type="number" min="0" max="100" step="1" value="100" aria-label="不透明度の数値" disabled></label><label>塗りの強さ <output id="brushFlowValue">100%</output><input id="brushFlow" type="range" data-unit="%" min="0" max="100" step="1" value="100" disabled><input id="brushFlowNumber" type="number" min="0" max="100" step="1" value="100" aria-label="塗りの強さの数値" disabled></label><label>点の間隔 <output id="brushSpacingValue">9%</output><input id="brushSpacing" type="range" data-unit="%" min="1" max="100" step="1" value="9" disabled></label><label>筆圧変化の滑らかさ <output id="brushPressureValue">20%</output><input id="brushPressure" type="range" data-unit="%" min="0" max="100" step="1" value="20" disabled></label><label>手ブレ補正 <output id="brushStabilizationValue">25%</output><input id="brushStabilization" type="range" data-unit="%" min="0" max="100" step="1" value="25" disabled><input id="brushStabilizationNumber" type="number" min="0" max="100" step="1" value="100" aria-label="手ブレ補正の数値" disabled></label><label>紙の質感 <output id="brushTextureValue">0%</output><input id="brushTexture" type="range" data-unit="%" min="0" max="100" step="1" value="0" disabled></label><label class="checkbox-line"><input id="brushAzimuth" type="checkbox" disabled> ペンの傾きによる回転</label><label class="checkbox-line"><input id="brushTwist" type="checkbox" disabled> ペンのひねりによる回転</label></div><div class="m10-brush-settings"><label>手ブレ補正の使い方<select id="brushStabilizationScope"><option value="brush">このブラシ固有</option><option value="common">全ブラシ共通の値</option></select></label><label>端末の筆圧感度 <output id="devicePressureSensitivityValue">標準</output><input id="devicePressureSensitivity" type="range" data-unit="%" min="0" max="100" step="1" value="50"></label><small>右へ動かすと弱い筆圧でも強く反応。標準の50ではブラシ固有の筆圧設定を維持します。</small></div><div id="brushEditorAdvanced" class="brush-editor-advanced"><details class="brush-editor-section"><summary>筆圧に対する反応の曲線</summary><div class="brush-editor-section-body"><p>横方向が筆圧、縦方向が反応の強さです。線上を触れて点を追加・移動できます。数値でも調整できます。</p><svg id="brushCurveChart" class="brush-curve-chart" viewBox="0 0 120 120" role="group" aria-label="筆圧の反応を調整する曲線"></svg><div class="brush-curve-actions"><label>点 <select id="brushCurvePoint"></select></label><button id="brushCurveAdd" type="button">点を追加</button><button id="brushCurveDelete" type="button">点を削除</button><button id="brushCurveStraight" type="button">直線に戻す</button></div><div class="brush-curve-coordinates"><label>入力 <input id="brushCurveX" type="number" min="0" max="100" step=".01" value="0">%</label><label>出力 <input id="brushCurveY" type="number" min="0" max="100" step=".01" value="0">%</label></div></div></details><details class="brush-editor-section"><summary>入り抜きの細かな調整</summary><div class="brush-editor-section-body"><p>強制入り抜きを有効にすると、線の始まりと終わりの太さを独立して調整できます。</p><div class="brush-editor-control"><label for="brushFadeStart">入りの長さ</label><input id="brushFadeStart" type="range" data-unit="%" min="0" max="100" step="1" value="12"><input id="brushFadeStartNumber" type="number" min="0" max="100" step="1" value="12" aria-label="入りの長さの数値"></div><div class="brush-editor-control"><label for="brushFadeEnd">抜きの長さ</label><input id="brushFadeEnd" type="range" data-unit="%" min="0" max="100" step="1" value="40"><input id="brushFadeEndNumber" type="number" min="0" max="100" step="1" value="40" aria-label="抜きの長さの数値"></div><div class="brush-editor-control"><label for="brushFadeMin">最小の太さ</label><input id="brushFadeMin" type="range" data-unit="%" min="0" max="100" step="1" value="3"><input id="brushFadeMinNumber" type="number" min="0" max="100" step="1" value="3" aria-label="最小の太さの数値"></div></div></details><details class="brush-editor-section"><summary>ブラシ先端</summary><div class="brush-editor-section-body"><label>先端の形 <select id="brushTipShape"><option value="round">丸</option><option value="ellipse">楕円</option><option value="rect">四角</option><option value="bristle">毛束</option><option value="star">星</option><option value="leaf">葉</option><option value="mask">読み込んだ画像</option></select></label><label>先端画像を読み込む（最大64 pxに縮小）<input id="brushTipFile" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="brush-editor-control"><label for="brushHardness">輪郭の硬さ</label><input id="brushHardness" type="range" data-unit="%" min="0" max="100" step="1" value="100"><input id="brushHardnessNumber" type="number" min="0" max="100" step="1" value="100" aria-label="輪郭の硬さの数値"></div><div class="brush-editor-control"><label for="brushTipAspect">縦横比</label><input id="brushTipAspect" type="range" data-unit="%" min="1" max="100" step="1" value="100"><input id="brushTipAspectNumber" type="number" min="1" max="100" step="1" value="100" aria-label="縦横比の数値"></div><div class="brush-editor-control"><label for="brushTipAngle">先端の角度</label><input id="brushTipAngle" type="range" data-unit="°" min="-180" max="180" step="1" value="0"><input id="brushTipAngleNumber" type="number" min="-180" max="180" step="1" value="0" aria-label="先端の角度の数値"></div><label class="checkbox-line"><input id="brushTipFollow" type="checkbox"> 線の向きに合わせて先端を回す</label><p>鉛筆など専用の描画方式を使うブラシは、先端形状を固定します。</p></div></details><details class="brush-editor-section"><summary>紙の質感</summary><div class="brush-editor-section-body"><label>模様 <select id="brushTextureKind"><option value="paper">紙</option><option value="noise">粒状</option><option value="hatch">斜線</option><option value="image">読み込んだ画像</option></select></label><label>紙の質感に使う画像（最大64 pxに縮小）<input id="brushTextureFile" type="file" accept="image/png,image/jpeg,image/webp"></label><label>模様の固定先<select id="brushTextureSpace"><option value="paper">用紙</option><option value="tip">ブラシ先端</option></select></label><div class="brush-editor-control"><label for="brushTextureScale">模様の細かさ</label><input id="brushTextureScale" type="range" data-unit="倍" min="0.1" max="64" step="0.1" value="2"><input id="brushTextureScaleNumber" type="number" min="0.1" max="64" step="0.1" value="2" aria-label="模様の細かさの数値"></div><div class="brush-editor-control"><label for="brushTextureRotation">模様の角度</label><input id="brushTextureRotation" type="range" data-unit="°" min="-180" max="180" step="1" value="0"><input id="brushTextureRotationNumber" type="number" min="-180" max="180" step="1" value="0" aria-label="模様の角度の数値"></div><p>現在の通常ブラシでは、同時に利用できる質感の種類は1つまでです。</p></div></details><details class="brush-editor-section"><summary>手ブレ補正の詳細</summary><div class="brush-editor-section-body"><div class="brush-editor-control"><label for="brushStabilizationFast">速く動かしたときの補正</label><input id="brushStabilizationFast" type="range" data-unit="%" min="0" max="100" step="1" value="0"><input id="brushStabilizationFastNumber" type="number" min="0" max="100" step="1" value="0" aria-label="速く動かしたときの補正の数値"></div><label>速いときの補正の方向 <select id="brushStabilizationMode"><option value="increase">速いほど強くする</option><option value="reduce">速いほど弱くする</option></select></label><label class="checkbox-line"><input id="brushPrediction" type="checkbox"> 先端の動きを予測して表示する</label><p>予測は画面表示だけに使い、作品の線や保存内容は変更しません。</p><div class="brush-editor-control"><label for="brushWidthChange">筆圧による太さの急変を抑える</label><input id="brushWidthChange" type="range" min="0" max="16" step=".25" value="0"><input id="brushWidthChangeNumber" type="number" min="0" max="16" step=".25" value="0" aria-label="太さ変化の上限の数値"></div><p>0は制限なし。値を増やすと、筆圧による太さの変化を速く反映します。</p><p>補正を強くすると線の追従が遅く感じられる場合があります。</p></div></details><details class="brush-editor-section"><summary>粒の散らばり</summary><div class="brush-editor-section-body"><label class="checkbox-line"><input id="brushScatterEnabled" type="checkbox"> 粒を散らして描く</label><div class="brush-editor-control"><label for="brushScatterRadius">散らばる範囲</label><input id="brushScatterRadius" type="range" data-unit="%" min="0" max="200" step="1" value="0"><input id="brushScatterRadiusNumber" type="number" min="0" max="200" step="1" value="0" aria-label="散らばる範囲の数値"></div><p>多数の粒を描く設定は大きなキャンバスで重くなる場合があります。</p></div></details><details class="brush-editor-section"><summary>ペンの動きに反応する設定</summary><div class="brush-editor-section-body"><p>筆圧や描いた距離などに合わせて、太さ・濃さ・色・質感を変えられます。対応する値がない端末では代替値が使われます。</p><div id="brushDynamicsList" aria-label="反応設定の一覧"></div><div class="brush-dynamics-add"><select id="brushDynamicsSource" aria-label="反応させる入力"><option value="pressure">筆圧</option><option value="velocity">ペンの速さ</option><option value="tilt">ペンの傾き</option></select><select id="brushDynamicsTarget" aria-label="変える対象"><option value="size">太さ</option><option value="opacity">濃さ</option><option value="flow">塗りの量</option></select><button type="button" id="brushDynamicsAdd">反応を追加</button></div><p>詳細な組み合わせでは描画が重くなる場合があります。保存は「自作ブラシ」に複製して行えます。</p></div></details></div><label class="checkbox-line"><input id="force" type="checkbox" disabled> 強制入り抜き</label></details><details class="brush-disclosure"><summary>ペン・指の設定</summary><label class="checkbox-line"><input id="finger" type="checkbox"> 指で描く</label><label class="checkbox-line"><input id="palmGuard" type="checkbox" checked> ペン使用中に手のひらの接触を抑える</label><label class="checkbox-line"><input id="penBarrelErase" type="checkbox"> 対応ペンの横ボタンを押しながら消す</label><label class="checkbox-line"><input id="eraserSizeLink" type="checkbox"> 一時消しゴムをブラシと同じ太さにする</label><label class="checkbox-line"><input id="brushCursorEnabled" type="checkbox"> ブラシの輪郭と中心を表示</label></details>';
    case 'right.navigator':return '<div class="box-actions"><button type="button" data-action="fitView">全体表示</button><button type="button" data-action="view100">100%</button><button type="button" data-action="actualPixels">実画素表示</button><button type="button" data-action="resetRotation">回転を戻す</button></div><details class="guide-settings"><summary>直線定規</summary><label class="checkbox-line"><input id="guideEnabled" type="checkbox"> 直線に沿って描く</label><label>定規の角度 <input id="guideAngle" type="number" min="0" max="359" step="1" value="0">°</label><label>定規への吸着 <input id="guideStrength" type="range" data-unit="%" min="0" max="100" step="1" value="100"> <output id="guideStrengthValue">100%</output></label><label class="checkbox-line"><input id="guideApplyEraser" type="checkbox"> 消しゴムにも適用</label><small>線を描き始めた場所を通る定規です。Shiftを押しながら描くと一時解除します。</small></details><label class="checkbox-line"><input id="seamless" type="checkbox"> 繰り返し表示</label><label>繰り返し数 <select id="seamlessCount" disabled><option value="0">制限なし</option><option value="1">3 × 3</option><option value="2">5 × 5</option><option value="3">7 × 7</option><option value="4">9 × 9</option></select></label><label class="checkbox-line"><input id="pixelGridToggle" type="checkbox"> ピクセルグリッド</label><label>グリッドの表示倍率 <input id="pixelGridThreshold" type="number" min="400" max="6400" step="100" value="800">%</label><label>グリッドの色 <input id="pixelGridColor" type="color" value="#596984"></label><label class="checkbox-line"><input id="rotationSnap" type="checkbox"> 回転を直角で止めやすくする</label><div class="box-actions"><button id="selectionStart" type="button">四角く範囲を選ぶ</button><button id="selectionClear" type="button">選択を解除</button></div><small id="selectionStatus" role="status">選択範囲なし。範囲を描くと、その内側だけに描画します。</small>';
    case 'right.effects':return '';
    case 'right.automation':return ''; // Populated by installSimpleMacros.
    case 'right.history':return '<button id="openArtworkHistory" type="button">作品の履歴を開く</button>';
    case 'right.document':return '<div class="scalar-row"><label for="newCanvasWidth">新しい作品</label><input id="newCanvasWidth" aria-label="新しい作品の横幅（px）" type="number" min="1" max="8192" value="512"><span>×</span><input id="newCanvasHeight" aria-label="新しい作品の縦幅（px）" type="number" min="1" max="8192" value="384"></div><div class="box-actions"><button id="documentInfoOpen" type="button">作品情報</button><button id="cropStart" type="button">切り抜き</button><button id="restoreCropOutside" type="button">切り抜きの外側を復元</button><button id="canvasResizeStart" type="button">キャンバスサイズを変更</button><button id="imageResizeStart" type="button">画像の大きさを変更</button></div><div class="box-actions"><button type="button" data-action="new">'+icon('plus')+' 新規作成</button><button type="button" data-action="open">'+icon('open')+' 作品を開く</button><button type="button" data-action="save">'+icon('save')+' 作品を保存</button><button type="button" data-action="exportImage">'+icon('export')+' 画像を書き出す</button><button type="button" data-action="recover">'+icon('recover')+' 自動保存から戻す</button></div>';
    case 'right.workspace':return colorSettingsMarkup()+'<label class="width-control">右側の幅 <output id="widthValue">344px</output><input id="width" type="range" data-unit="px" min="288" max="440" value="344"></label><div class="box-actions"><button id="narrower" type="button">狭く</button><button id="wider" type="button">広く</button><button id="resetWidth" type="button">元の幅</button></div><button id="hideWorkspace" type="button">右側を閉じる</button>';
    default:return disabled('この機能');
  }
};
function boxes():string{
