  });};
  const setRecoveryCandidates=(candidates:readonly RecoverySummary[])=>{
    recovery=candidates.filter(x=>{try{return BigInt(x.protectedThrough)>0n;}catch{return false;}});
    if(screen==='recovery')showRecovery();
